/* ts2021 Noise IK interop: the initiation must match the one Tailscale's own
 * controlbase.Server accepted, and the captured server response and records
 * must verify and decrypt (vectors_go.h, generated by testbed/vectors). */
#include <sys/socket.h>
#include <unistd.h>

#include "tt.h"
#include "crypto.h"
#include "tn.h"
#include "vectors_go.h"

int main(void)
{
	tn_noise_hs hs;
	uint8_t init[TN_NOISE_INIT_LEN];
	static tn_nconn nc;
	static tn_tr tr;

	CHECK(tn_noise_initiate(&hs, init, GV_NOISE_CAPVER, gv_noise_machine_priv, gv_noise_control_pub,
				gv_noise_eph_priv) == 0);
	CHECK(sizeof gv_noise_init == TN_NOISE_INIT_LEN);
	CHECK_MEM(init, gv_noise_init, TN_NOISE_INIT_LEN);
	CHECK(init[0] == 0 && init[1] == TN_CAPVER && init[2] == 1 && init[4] == 96);

	/* A tampered response must fail; keep a copy of the handshake state. */
	tn_noise_hs hs2 = hs;
	uint8_t bad[TN_NOISE_RESP_LEN];
	memcpy(bad, gv_noise_resp, sizeof bad);
	bad[40] ^= 0x80;
	CHECK(tn_noise_finish(&hs2, bad, gv_noise_machine_priv, &nc) == TN_E_CRYPTO);

	CHECK(tn_noise_finish(&hs, gv_noise_resp, gv_noise_machine_priv, &nc) == 0);
	CHECK_MEM(nc.tx_key, gv_noise_k1, 32);
	CHECK_MEM(nc.rx_key, gv_noise_k2, 32);

	/* Records through a real socket. */
	int sv[2];
	CHECK(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
	memset(&tr, 0, sizeof tr);
	tr.fd = sv[0];
	tr.wake_fd = -1;
	nc.tr = &tr;
	CHECK(write(sv[1], gv_noise_server_rec, sizeof gv_noise_server_rec) == (ssize_t)sizeof gv_noise_server_rec);
	char msg[128] = {0};
	size_t ml = strlen(gv_noise_server_msg);
	CHECK(tn_nconn_read_full(&nc, msg, ml) == 0);
	CHECK(!memcmp(msg, gv_noise_server_msg, ml));
	CHECK(nc.rx_n == 1);

	/* Our second record (counter 1) equals what Go sealed with k1. */
	uint8_t out[256];
	tn_noise_seal_record(&nc, out, (const uint8_t *)"x", 1);
	size_t n = tn_noise_seal_record(&nc, out, (const uint8_t *)gv_noise_client_msg, strlen(gv_noise_client_msg));
	CHECK(n == sizeof gv_noise_client_rec1);
	CHECK_MEM(out, gv_noise_client_rec1, n);

	/* A replayed record (rx counter already advanced) fails authentication. */
	CHECK(write(sv[1], gv_noise_server_rec, sizeof gv_noise_server_rec) == (ssize_t)sizeof gv_noise_server_rec);
	CHECK(tn_nconn_read_full(&nc, msg, ml) == TN_E_CRYPTO);

	/* Oversized and wrong-type record headers are rejected before reading a body. */
	nc.pt_pos = nc.pt_len = 0;
	uint8_t hdr[3] = {0x04, 0xff, 0xff};
	CHECK(write(sv[1], hdr, 3) == 3);
	CHECK(tn_nconn_read_full(&nc, msg, 1) == TN_E_PROTO);
	uint8_t hdr2[3] = {0x02, 0x00, 0x20};
	CHECK(write(sv[1], hdr2, 3) == 3);
	CHECK(tn_nconn_read_full(&nc, msg, 1) == TN_E_PROTO);
	close(sv[1]);
	CHECK(tn_nconn_read_full(&nc, msg, 1) == TN_E_IO); /* EOF */
	close(sv[0]);
	return tt_done("test_noise");
}
